1	// Package editor exposes editor-menu-style operations — "go to definition",
2	// "find references" — as MCP tools, backed by the language servers
3	// internal/lsp manages. It translates between the MCP tool's simple
4	// file/line/column shape and the LSP protocol details a coding agent should
5	// never have to know about.
6	package editor
7	
8	import (
9		"context"
10		"fmt"
11		"path/filepath"
12	
13		"github.com/modelcontextprotocol/go-sdk/mcp"
14	
15		"github.com/gustavofsantos/waythrough/internal/config"
16		"github.com/gustavofsantos/waythrough/internal/lsp"
17	)
18	
19	// New builds the MCP server exposing editor operations backed by manager's
20	// configured language servers, routed by each file's extension per cfg.
21	func New(manager *lsp.Manager, cfg config.Config) *mcp.Server {
22		e := &editor{manager: manager, serverForExt: routeByExtension(cfg)}
23	
24		server := mcp.NewServer(&mcp.Implementation{Name: "waythrough", Version: "0.1.0"}, nil)
25		mcp.AddTool(server, &mcp.Tool{
26			Name:        "get_definition",
27			Description: "Find where the symbol at a file position is defined.",
28		}, e.getDefinition)
29		mcp.AddTool(server, &mcp.Tool{
30			Name:        "list_references",
31			Description: "List every place the symbol at a file position is used.",
32		}, e.listReferences)
33		mcp.AddTool(server, &mcp.Tool{
34			Name: "rename_symbol",
35			Description: "Compute the edits that rename the symbol at a file position, " +
36				"across every file it touches. Does not write the edits to disk — " +
37				"apply them yourself. Columns are a byte-offset approximation and may " +
38				"be off on lines with non-ASCII characters before the edit.",
39		}, e.renameSymbol)
40		mcp.AddTool(server, &mcp.Tool{
41			Name: "signature_help",
42			Description: "List the signatures the call at a file position could match, " +
43				"and say which signature and which parameter that position is on. " +
44				"Use it inside a call to learn what the next argument must be.",
45		}, e.signatureHelp)
46		mcp.AddTool(server, &mcp.Tool{
47			Name: "get_diagnostics",
48			Description: "List the problems a language server finds in a file: where each " +
49				"one is, how serious it is, and what it says. Use it instead of reading " +
50				"compiler or linter output by hand.",
51		}, e.getDiagnostics)
52	
53		return server
54	}
55	
56	type editor struct {
57		manager      *lsp.Manager
58		serverForExt map[string]string
59	}
60	
61	// routeByExtension builds the extension-to-server routing table.
62	//
63	// Precondition: config.Validate(cfg) returned no error. It is the one
64	// enforcer of the rule this table depends on — at most one entry claims any
65	// one extension. Given a config that breaks it, the last entry to claim an
66	// extension wins here, in silence, and an agent gets answers from a server
67	// it never picked. cmd/waythrough reaches this only through serve, which
68	// validates first (internal/cli/serve.go), and a CLI test pins that.
69	func routeByExtension(cfg config.Config) map[string]string {
70		routes := make(map[string]string)
71		for _, entry := range cfg.LanguageServers {
72			for ext := range entry.Filetypes {
73				routes[ext] = entry.Name
74			}
75		}
76		return routes
77	}
78	
79	type position struct {
80		File   string `json:"file" jsonschema:"file path, absolute or relative to the project root"`
81		Line   int    `json:"line" jsonschema:"1-based line number"`
82		Column int    `json:"column" jsonschema:"1-based column number"`
83	}
84	
85	type location struct {
86		File   string `json:"file"`
87		Line   int    `json:"line"`
88		Column int    `json:"column"`
89	}
90	
91	type locationsOutput struct {
92		Locations []location `json:"locations"`
93	}
94	
95	type renamePosition struct {
96		position
97		NewName string `json:"new_name" jsonschema:"the new name to give the symbol"`
98	}
99	
100	// edit is a range replacement an agent applies verbatim, so its columns —
101	// unlike location's — are not merely a navigation hint: an off-by-N on a
102	// line with non-ASCII characters before the edit corrupts the file.
103	type edit struct {
104		File        string `json:"file"`
105		StartLine   int    `json:"start_line"`
106		StartColumn int    `json:"start_column"`
107		EndLine     int    `json:"end_line"`
108		EndColumn   int    `json:"end_column"`
109		NewText     string `json:"new_text"`
110	}
111	
112	type editsOutput struct {
113		Edits []edit `json:"edits"`
114	}
115	
116	// document is the input of a tool that asks about a file as a whole, rather
117	// than about one position in it.
118	type document struct {
119		File string `json:"file" jsonschema:"file path, absolute or relative to the project root"`
120	}
121	
122	type diagnostic struct {
123		StartLine   int    `json:"start_line"`
124		StartColumn int    `json:"start_column"`
125		EndLine     int    `json:"end_line"`
126		EndColumn   int    `json:"end_column"`
127		Severity    string `json:"severity,omitempty"`
128		Message     string `json:"message"`
129		Source      string `json:"source,omitempty"`
130		Code        string `json:"code,omitempty"`
131	}
132	
133	type diagnosticsOutput struct {
134		Diagnostics []diagnostic `json:"diagnostics"`
135	}
136	
137	type signature struct {
138		Label         string   `json:"label"`
139		Documentation string   `json:"documentation,omitempty"`
140		Parameters    []string `json:"parameters"`
141	}
142	
143	// signatureHelpOutput names its two indices as indices, not as positions:
144	// each one counts from 0, unlike the 1-based line and column every other
145	// tool here speaks in. ActiveSignature indexes Signatures, ActiveParameter
146	// indexes that signature's Parameters, and neither means anything when
147	// Signatures is empty.
148	type signatureHelpOutput struct {
149		Signatures      []signature `json:"signatures"`
150		ActiveSignature int         `json:"active_signature" jsonschema:"0-based signature index"`
151		ActiveParameter int         `json:"active_parameter" jsonschema:"0-based parameter index"`
152	}
153	
154	func (e *editor) getDefinition(
155		ctx context.Context, _ *mcp.CallToolRequest, in position,
156	) (*mcp.CallToolResult, locationsOutput, error) {
157		name, err := e.resolveTarget(in)
158		if err != nil {
159			return nil, locationsOutput{}, err
160		}
161	
162		locations, err := e.manager.Definition(ctx, name, in.File, in.Line, in.Column)
163		if err != nil {
164			return nil, locationsOutput{}, err
165		}
166		return nil, toLocationsOutput(locations), nil
167	}
168	
169	func (e *editor) listReferences(
170		ctx context.Context, _ *mcp.CallToolRequest, in position,
171	) (*mcp.CallToolResult, locationsOutput, error) {
172		name, err := e.resolveTarget(in)
173		if err != nil {
174			return nil, locationsOutput{}, err
175		}
176	
177		locations, err := e.manager.References(ctx, name, in.File, in.Line, in.Column)
178		if err != nil {
179			return nil, locationsOutput{}, err
180		}
181		return nil, toLocationsOutput(locations), nil
182	}
183	
184	func (e *editor) renameSymbol(
185		ctx context.Context, _ *mcp.CallToolRequest, in renamePosition,
186	) (*mcp.CallToolResult, editsOutput, error) {
187		if in.NewName == "" {
188			return nil, editsOutput{}, fmt.Errorf("new_name must not be empty")
189		}
190	
191		name, err := e.resolveTarget(in.position)
192		if err != nil {
193			return nil, editsOutput{}, err
194		}
195	
196		edits, err := e.manager.Rename(ctx, name, in.File, in.Line, in.Column, in.NewName)
197		if err != nil {
198			return nil, editsOutput{}, err
199		}
200		return nil, toEditsOutput(edits), nil
201	}
202	
203	func (e *editor) signatureHelp(
204		ctx context.Context, _ *mcp.CallToolRequest, in position,
205	) (*mcp.CallToolResult, signatureHelpOutput, error) {
206		name, err := e.resolveTarget(in)
207		if err != nil {
208			return nil, signatureHelpOutput{}, err
209		}
210	
211		help, err := e.manager.SignatureHelp(ctx, name, in.File, in.Line, in.Column)
212		if err != nil {
213			return nil, signatureHelpOutput{}, err
214		}
215		return nil, toSignatureHelpOutput(help), nil
216	}
217	
218	func (e *editor) getDiagnostics(
219		ctx context.Context, _ *mcp.CallToolRequest, in document,
220	) (*mcp.CallToolResult, diagnosticsOutput, error) {
221		name, err := e.serverForFile(in.File)
222		if err != nil {
223			return nil, diagnosticsOutput{}, err
224		}
225	
226		diagnostics, err := e.manager.Diagnostics(ctx, name, in.File)
227		if err != nil {
228			return nil, diagnosticsOutput{}, err
229		}
230		return nil, toDiagnosticsOutput(diagnostics), nil
231	}
232	
233	// resolveTarget validates a 1-based position and finds which configured
234	// server handles in.File's extension — the checks every editor operation on
235	// a position needs before it can ask a language server anything.
236	func (e *editor) resolveTarget(in position) (string, error) {
237		if in.Line < 1 || in.Column < 1 {
238			return "", fmt.Errorf(
239				"line and column are 1-based and must be at least 1, got line=%d column=%d",
240				in.Line, in.Column)
241		}
242		return e.serverForFile(in.File)
243	}
244	
245	// serverForFile finds which configured server handles file's extension. It
246	// is the whole check for a tool that asks about a file rather than about a
247	// position in it, since such a tool has no line or column to validate.
248	func (e *editor) serverForFile(file string) (string, error) {
249		ext := filepath.Ext(file)
250		name, ok := e.serverForExt[ext]
251		if !ok {
252			return "", fmt.Errorf("no configured language server for file extension %q", ext)
253		}
254		return name, nil
255	}
256	
257	func toLocationsOutput(locations []lsp.Location) locationsOutput {
258		out := locationsOutput{Locations: make([]location, len(locations))}
259		for i, loc := range locations {
260			out.Locations[i] = location{File: loc.File, Line: loc.Line, Column: loc.Column}
261		}
262		return out
263	}
264	
265	func toDiagnosticsOutput(diagnostics []lsp.Diagnostic) diagnosticsOutput {
266		out := diagnosticsOutput{Diagnostics: make([]diagnostic, len(diagnostics))}
267		for i, d := range diagnostics {
268			out.Diagnostics[i] = diagnostic{
269				StartLine:   d.StartLine,
270				StartColumn: d.StartColumn,
271				EndLine:     d.EndLine,
272				EndColumn:   d.EndColumn,
273				Severity:    d.Severity,
274				Message:     d.Message,
275				Source:      d.Source,
276				Code:        d.Code,
277			}
278		}
279		return out
280	}
281	
282	func toSignatureHelpOutput(help lsp.SignatureHelp) signatureHelpOutput {
283		out := signatureHelpOutput{
284			Signatures:      make([]signature, len(help.Signatures)),
285			ActiveSignature: help.ActiveSignature,
286			ActiveParameter: help.ActiveParameter,
287		}
288		for i, s := range help.Signatures {
289			out.Signatures[i] = signature{
290				Label:         s.Label,
291				Documentation: s.Documentation,
292				Parameters:    s.Parameters,
293			}
294		}
295		return out
296	}
297	
298	func toEditsOutput(edits []lsp.Edit) editsOutput {
299		out := editsOutput{Edits: make([]edit, len(edits))}
300		for i, e := range edits {
301			out.Edits[i] = edit{
302				File:        e.File,
303				StartLine:   e.StartLine,
304				StartColumn: e.StartColumn,
305				EndLine:     e.EndLine,
306				EndColumn:   e.EndColumn,
307				NewText:     e.NewText,
308			}
309		}
310		return out
311	}
