1	// Command fakelsp is a minimal, scriptable language server used only by
2	// internal/lsp's tests. It speaks real LSP Content-Length framing so the
3	// tests exercise the same transport a real language server uses, without
4	// requiring clojure-lsp or lua-language-server to be installed.
5	package main
6	
7	import (
8		"bufio"
9		"encoding/json"
10		"flag"
11		"fmt"
12		"io"
13		"os"
14		"strings"
15		"sync"
16		"time"
17	
18		"go.lsp.dev/uri"
19	)
20	
21	type message struct {
22		JSONRPC string          `json:"jsonrpc"`
23		ID      json.RawMessage `json:"id,omitempty"`
24		Method  string          `json:"method,omitempty"`
25		Params  json.RawMessage `json:"params,omitempty"`
26		Result  json.RawMessage `json:"result,omitempty"`
27		Error   json.RawMessage `json:"error,omitempty"`
28	}
29	
30	var (
31		writeMu          sync.Mutex
32		out              = bufio.NewWriter(os.Stdout)
33		nextID           = 1000
34		nextIDMu         sync.Mutex
35		progress         = flag.Bool("progress", false, "report a workDoneProgress cycle for the initial load, if the client advertised support")
36		progressDelay    = flag.Duration("progress-delay", 20*time.Millisecond, "time between the progress begin and end notifications")
37		crash            = flag.Bool("crash", false, "exit(1) immediately instead of speaking the protocol, to simulate a server that fails to start")
38		crashMarker      = flag.String("crash-marker", "", "path to a marker file: crash once if it does not exist yet, then behave normally on every later run")
39		ignoreExit       = flag.Bool("ignore-exit", false, "acknowledge shutdown but never act on exit, to simulate a server that will not stop on its own")
40		definitionLine   = flag.Int("definition-line", -1, "0-based line to answer textDocument/definition with, in the requested document; negative means no definition")
41		definitionColumn = flag.Int("definition-column", 0, "0-based character to answer textDocument/definition with")
42		referencesLine   = flag.Int("references-line", -1, "0-based line of the first canned textDocument/references location; negative means no references")
43		referencesColumn = flag.Int("references-column", 0, "0-based character of every canned textDocument/references location")
44		referencesCount  = flag.Int("references-count", 1, "how many canned locations to answer textDocument/references with, at consecutive lines from -references-line")
45		renameLine       = flag.Int("rename-line", -1, "0-based line of the canned textDocument/rename edit in the requested document; negative means no rename")
46		renameColumn     = flag.Int("rename-column", 0, "0-based character where the canned edit in the requested document starts")
47		renameLength     = flag.Int("rename-length", 0, "number of characters the canned edit in the requested document replaces")
48		renameOtherFile  = flag.String("rename-other-file", "", "path to a second file to include a canned edit for, proving a rename can span files; empty means one edit only")
49		renameOtherLine  = flag.Int("rename-other-line", 0, "0-based line of the canned edit in -rename-other-file")
50		renameOtherCol   = flag.Int("rename-other-column", 0, "0-based character where the canned edit in -rename-other-file starts")
51		renameOtherLen   = flag.Int("rename-other-length", 0, "number of characters the canned edit in -rename-other-file replaces")
52		signatureHelp    = flag.String("signature-help", "", "raw JSON result to answer textDocument/signatureHelp with; empty means no signature help (null). A signature help result nests signatures, per-parameter labels, and two levels of active-index, so a test states the whole canned payload here rather than through one scalar flag per field")
53		pullDiagnostics  = flag.Bool("pull-diagnostics", false, "advertise diagnosticProvider in the initialize result, the capability a client must see before it may ask for diagnostics")
54		diagnostics      = flag.String("diagnostics", "", "raw JSON result to answer textDocument/diagnostic with, in the same spirit as -signature-help; empty means a full report holding no diagnostics, which is what a clean file gets")
55		requestLog       = flag.String("request-log", "", "path to a file that receives the method name of every request and notification handled, one per line — lets a test assert Waythrough never sent a request at all, not merely that it disliked the answer")
56		syncLog          = flag.String("sync-log", "", "path to a file that receives one JSON line per didOpen/didChange notification, recording the method, uri, version, and full text sent — lets a test assert Waythrough actually synced current content, not just that some document is open")
57	
58		openDocs       = map[string]bool{}
59		syncLogFile    *os.File
60		requestLogFile *os.File
61		logMu          sync.Mutex
62	)
63	
64	func main() {
65		flag.Parse()
66	
67		if *crash {
68			os.Exit(1)
69		}
70	
71		if *crashMarker != "" {
72			if _, err := os.Stat(*crashMarker); err != nil {
73				_ = os.WriteFile(*crashMarker, []byte("crashed"), 0o644)
74				os.Exit(1)
75			}
76		}
77	
78		syncLogFile = openLog("sync-log", *syncLog)
79		requestLogFile = openLog("request-log", *requestLog)
80	
81		r := bufio.NewReader(os.Stdin)
82		for {
83			msg, err := readMessage(r)
84			if err != nil {
85				return
86			}
87			logRequest(msg.Method)
88	
89			switch msg.Method {
90			case "initialize":
91				handleInitialize(msg)
92			case "initialized":
93				if *progress {
94					go runProgressCycle(workDoneProgressAdvertised(msg))
95				}
96			case "shutdown":
97				respond(msg.ID, "null")
98			case "exit":
99				if *ignoreExit {
100					continue
101				}
102				_ = out.Flush()
103				os.Exit(0)
104			case "textDocument/didOpen", "textDocument/didChange":
105				openDocs[documentURI(msg.Params)] = true
106				logSyncEvent(msg.Method, msg.Params)
107			case "textDocument/definition":
108				handleDefinition(msg)
109			case "textDocument/references":
110				handleReferences(msg)
111			case "textDocument/rename":
112				handleRename(msg)
113			case "textDocument/signatureHelp":
114				handleSignatureHelp(msg)
115			case "textDocument/diagnostic":
116				handleDiagnostic(msg)
117			}
118		}
119	}
120	
121	var lastInitializeParams json.RawMessage
122	
123	func handleInitialize(msg message) {
124		lastInitializeParams = msg.Params
125	
126		capabilities := ""
127		if *pullDiagnostics {
128			capabilities = `"diagnosticProvider":` +
129				`{"interFileDependencies":false,"workspaceDiagnostics":false}`
130		}
131		respond(msg.ID, fmt.Sprintf(`{"capabilities":{%s}}`, capabilities))
132	}
133	
134	func respond(id json.RawMessage, result string) {
135		writeMessage(message{JSONRPC: "2.0", ID: id, Result: json.RawMessage(result)})
136	}
137	
138	func respondError(id json.RawMessage, code int, msg string) {
139		writeMessage(message{
140			JSONRPC: "2.0",
141			ID:      id,
142			Error:   json.RawMessage(fmt.Sprintf(`{"code":%d,"message":%q}`, code, msg)),
143		})
144	}
145	
146	// documentURI reads the textDocument.uri field common to didOpen, didChange,
147	// and definition params.
148	func documentURI(params json.RawMessage) string {
149		var v struct {
150			TextDocument struct {
151				URI string `json:"uri"`
152			} `json:"textDocument"`
153		}
154		if err := json.Unmarshal(params, &v); err != nil {
155			return ""
156		}
157		return v.TextDocument.URI
158	}
159	
160	// openLog opens one of the append-only log files a test reads afterwards.
161	// An empty path means the test asked for no such log.
162	func openLog(name, path string) *os.File {
163		if path == "" {
164			return nil
165		}
166		f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
167		if err != nil {
168			fmt.Fprintln(os.Stderr, name+":", err)
169			os.Exit(1)
170		}
171		return f
172	}
173	
174	// logRequest appends one method name to -request-log, if set, for every
175	// message handled, whether or not this fake answers it.
176	func logRequest(method string) {
177		if requestLogFile == nil || method == "" {
178			return
179		}
180		logMu.Lock()
181		defer logMu.Unlock()
182		_, _ = fmt.Fprintln(requestLogFile, method)
183	}
184	
185	// logSyncEvent appends one JSON line to -sync-log, if set, recording the
186	// document text a didOpen/didChange notification actually carried — a
187	// didOpen's own textDocument.text, or a didChange's first contentChanges
188	// entry, since Waythrough only ever sends whole-document changes.
189	func logSyncEvent(method string, params json.RawMessage) {
190		if syncLogFile == nil {
191			return
192		}
193	
194		var v struct {
195			TextDocument struct {
196				URI     string `json:"uri"`
197				Version int32  `json:"version"`
198				Text    string `json:"text"`
199			} `json:"textDocument"`
200			ContentChanges []struct {
201				Text string `json:"text"`
202			} `json:"contentChanges"`
203		}
204		if err := json.Unmarshal(params, &v); err != nil {
205			return
206		}
207	
208		text := v.TextDocument.Text
209		if len(v.ContentChanges) > 0 {
210			text = v.ContentChanges[0].Text
211		}
212	
213		line, err := json.Marshal(struct {
214			Method  string `json:"method"`
215			URI     string `json:"uri"`
216			Version int32  `json:"version"`
217			Text    string `json:"text"`
218		}{Method: method, URI: v.TextDocument.URI, Version: v.TextDocument.Version, Text: text})
219		if err != nil {
220			return
221		}
222	
223		logMu.Lock()
224		defer logMu.Unlock()
225		_, _ = syncLogFile.Write(append(line, '\n'))
226	}
227	
228	// handleDefinition answers textDocument/definition. It errors if the
229	// document was never opened, so a test can tell whether Waythrough synced
230	// the file before asking about it, and otherwise returns the location the
231	// -definition-line/-definition-column flags describe, or null if
232	// -definition-line is negative.
233	func handleDefinition(msg message) {
234		docURI := documentURI(msg.Params)
235		if !openDocs[docURI] {
236			respondError(msg.ID, -32000, fmt.Sprintf("document not open: %s", docURI))
237			return
238		}
239		if *definitionLine < 0 {
240			respond(msg.ID, "null")
241			return
242		}
243		respond(msg.ID, fmt.Sprintf(
244			`{"uri":%q,"range":{"start":{"line":%d,"character":%d},"end":{"line":%d,"character":%d}}}`,
245			docURI, *definitionLine, *definitionColumn, *definitionLine, *definitionColumn,
246		))
247	}
248	
249	// handleReferences answers textDocument/references. Like handleDefinition,
250	// it errors if the document was never opened, and otherwise returns
251	// -references-count canned locations starting at -references-line, one per
252	// consecutive line, or an empty array if -references-line is negative.
253	func handleReferences(msg message) {
254		docURI := documentURI(msg.Params)
255		if !openDocs[docURI] {
256			respondError(msg.ID, -32000, fmt.Sprintf("document not open: %s", docURI))
257			return
258		}
259		if *referencesLine < 0 {
260			respond(msg.ID, "[]")
261			return
262		}
263	
264		locations := make([]string, *referencesCount)
265		for i := range locations {
266			line := *referencesLine + i
267			locations[i] = fmt.Sprintf(
268				`{"uri":%q,"range":{"start":{"line":%d,"character":%d},"end":{"line":%d,"character":%d}}}`,
269				docURI, line, *referencesColumn, line, *referencesColumn,
270			)
271		}
272		respond(msg.ID, "["+strings.Join(locations, ",")+"]")
273	}
274	
275	// handleRename answers textDocument/rename. Like handleDefinition, it errors
276	// if the requested document was never opened, and otherwise returns a
277	// WorkspaceEdit built from the -rename-* flags: one edit at the requested
278	// document's canned position, plus a second edit in -rename-other-file when
