413			if err != nil {
414				return message{}, fmt.Errorf("read header line: %w", err)
415			}
416			if line == "\r\n" {
417				break
418			}
419			_, _ = fmt.Sscanf(line, "Content-Length: %d", &length)
420		}
421	
422		body := make([]byte, length)
423		if _, err := io.ReadFull(r, body); err != nil {
424			return message{}, fmt.Errorf("read body of %d bytes: %w", length, err)
425		}
