			if err := proc.handshake(ctx, m.root); err == nil {
				go proc.negotiateReadiness(ctx, m.progressDebounce)
			}
			proc.wait()
		}

		if proc.shutdownRequested() {
			return
		}
		select {
		case <-ctx.Done():
			return
		default:
		}

