// lingeringServer is a command that starts, records its own pid, and then
// stays alive reading its stdin without ever speaking the protocol. It is
// what a spec needs to ask whether a spawn left a process behind: a real
// language server would exit on its own and answer the question either way.
func lingeringServer(pidPath string) config.LanguageServer {
	return config.LanguageServer{
		Name:    "lingering",
		Command: "sh",
		// exec replaces the shell, so the pid written here is the pid of the
		// process the manager owns.
		Args: []string{"-c", "echo $$ > " + pidPath + "; exec cat"},
	}
}

// spawnedPid waits for lingeringServer to record its pid and returns it.
